package com.daytracker.reading;

import java.util.UUID;

import jakarta.validation.constraints.NotNull;

import com.daytracker.reading.Book.BookStatus;

public final class BookRequests {

	private BookRequests() {
	}

	/** The id is generated by the client so a retried create is idempotent. */
	public record Create(@NotNull UUID id, @NotNull String title, String author, @NotNull Integer totalPages,
			Integer initialPage, BookStatus status) {
	}

	/**
	 * Null properties are left unchanged. The author is the only property that
	 * can be cleared, by sending an empty string.
	 */
	public record Update(@NotNull Long version, String title, String author, Integer totalPages, Integer initialPage,
			BookStatus status, Boolean archived) {
	}

}
